"use client"

import { useState, useEffect } from "react"
import { personas } from "@/lib/personas"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Save, Lock, FileText, CheckCircle, AlertCircle } from "lucide-react"

export default function AdminKnowledgePage() {
    const [password, setPassword] = useState("")
    const [isAuthenticated, setIsAuthenticated] = useState(false)
    const [selectedPersonaId, setSelectedPersonaId] = useState(personas[0].id)
    const [content, setContent] = useState("")
    const [isLoading, setIsLoading] = useState(false)
    const [status, setStatus] = useState<{ type: "success" | "error"; message: string } | null>(null)

    // Load content when persona changes
    useEffect(() => {
        if (isAuthenticated && selectedPersonaId) {
            fetchContent()
        }
    }, [selectedPersonaId, isAuthenticated])

    const fetchContent = async () => {
        setIsLoading(true)
        try {
            const res = await fetch(`/api/admin/knowledge?personaId=${selectedPersonaId}`)
            const data = await res.json()
            setContent(data.content || "")
        } catch (error) {
            console.error("Failed to load content", error)
        } finally {
            setIsLoading(false)
        }
    }

    const handleSave = async () => {
        setIsLoading(true)
        setStatus(null)
        try {
            const res = await fetch("/api/admin/knowledge", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    personaId: selectedPersonaId,
                    content,
                    password,
                }),
            })

            if (!res.ok) {
                throw new Error("Failed to save")
            }

            setStatus({ type: "success", message: "Knowledge base updated successfully!" })
        } catch (error) {
            setStatus({ type: "error", message: "Failed to save changes. Check password." })
        } finally {
            setIsLoading(false)
        }
    }

    const handleLogin = (e: React.FormEvent) => {
        e.preventDefault()
        if (password) setIsAuthenticated(true)
    }

    if (!isAuthenticated) {
        return (
            <div className="flex min-h-screen items-center justify-center bg-gray-50">
                <div className="w-full max-w-md space-y-8 rounded-xl bg-white p-10 shadow-lg">
                    <div className="text-center">
                        <Lock className="mx-auto h-12 w-12 text-gray-400" />
                        <h2 className="mt-6 text-3xl font-extrabold text-gray-900">Admin Access</h2>
                        <p className="mt-2 text-sm text-gray-600">Enter password to manage knowledge bases</p>
                    </div>
                    <form className="mt-8 space-y-6" onSubmit={handleLogin}>
                        <Input
                            type="password"
                            required
                            placeholder="Password"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            className="w-full"
                        />
                        <Button type="submit" className="w-full bg-[#7B8FD8] hover:bg-[#6B7FC8]">
                            Sign in
                        </Button>
                    </form>
                </div>
            </div>
        )
    }

    return (
        <div className="min-h-screen bg-gray-50 p-8">
            <div className="mx-auto max-w-6xl">
                <header className="mb-8 flex items-center justify-between">
                    <div>
                        <h1 className="text-3xl font-bold text-gray-900">Knowledge Base Manager</h1>
                        <p className="mt-2 text-gray-600">Edit markdown content for each persona</p>
                    </div>
                    <Button variant="outline" onClick={() => setIsAuthenticated(false)}>
                        Logout
                    </Button>
                </header>

                <div className="grid gap-8 lg:grid-cols-4">
                    {/* Sidebar - Persona Selection */}
                    <div className="space-y-4">
                        <div className="rounded-xl bg-white p-6 shadow-sm">
                            <h3 className="mb-4 font-semibold text-gray-900">Select Persona</h3>
                            <div className="space-y-2">
                                {personas.map((persona) => (
                                    <button
                                        key={persona.id}
                                        onClick={() => setSelectedPersonaId(persona.id)}
                                        className={`w-full rounded-lg px-4 py-3 text-left transition-colors ${selectedPersonaId === persona.id
                                                ? "bg-[#7B8FD8] text-white"
                                                : "bg-gray-50 text-gray-700 hover:bg-gray-100"
                                            }`}
                                    >
                                        <div className="font-medium">{persona.id}</div>
                                        <div className="truncate text-xs opacity-80">{persona.label}</div>
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>

                    {/* Main Area - Editor */}
                    <div className="lg:col-span-3">
                        <div className="flex h-[calc(100vh-12rem)] flex-col rounded-xl bg-white shadow-sm">
                            <div className="flex items-center justify-between border-b px-6 py-4">
                                <div className="flex items-center gap-2 text-gray-700">
                                    <FileText className="h-5 w-5" />
                                    <span className="font-medium">{selectedPersonaId}.md</span>
                                </div>

                                <div className="flex items-center gap-4">
                                    {status && (
                                        <div className={`flex items-center gap-2 text-sm ${status.type === "success" ? "text-green-600" : "text-red-600"
                                            }`}>
                                            {status.type === "success" ? <CheckCircle className="h-4 w-4" /> : <AlertCircle className="h-4 w-4" />}
                                            {status.message}
                                        </div>
                                    )}
                                    <Button
                                        onClick={handleSave}
                                        disabled={isLoading}
                                        className="gap-2 bg-[#7B8FD8] hover:bg-[#6B7FC8]"
                                    >
                                        <Save className="h-4 w-4" />
                                        {isLoading ? "Saving..." : "Save Changes"}
                                    </Button>
                                </div>
                            </div>

                            <div className="flex-1 p-0">
                                <textarea
                                    value={content}
                                    onChange={(e) => setContent(e.target.value)}
                                    className="h-full w-full resize-none p-6 font-mono text-sm outline-none"
                                    placeholder="# Enter markdown content here..."
                                />
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    )
}
